parameters.jsCode:
const item = $input.first();
let rawText = '';

// Extract reply text from whichever node succeeded
if (item.json.choices && item.json.choices[0] && item.json.choices[0].message) {
  rawText = item.json.choices[0].message.content || '';
} else if (item.json.text) {
  rawText = item.json.text;
} else if (item.json.message) {
  rawText = item.json.message;
}

if (!rawText || rawText.trim().length < 3) {
  rawText = 'Hai! Terima kasih kerana menghubungi SFV APPAREL. Ada apa-apa yang boleh kami bantu mengenai tempahan jersi anda hari ini?';
}

// Clean and humanize
let cleaned = rawText;
// Strip think blocks
cleaned = cleaned.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
// Replace vercel.app with production domain
cleaned = cleaned.replace(/https?:\/\/[a-zA-Z0-9_-]+\.vercel\.app/gi, 'https://sfvapparel.my');
// Remove markdown tables
cleaned = cleaned.replace(/\|[^\n]+\|/g, '');
// Format bolding **word** to *word*
cleaned = cleaned.replace(/\*\*([^*]+)\*\*/g, '*$1*');
// Remove UUIDs / system tokens
cleaned = cleaned.replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, '');
// Strip emojis cleanly
try {
  cleaned = cleaned.replace(/\p{Extended_Pictographic}/gu, '');
} catch(e) {}
// Clean excessive whitespace and dashes
cleaned = cleaned.replace(/---+/g, '');
cleaned = cleaned.replace(/[^\S\r\n]+/g, ' ');
cleaned = cleaned.replace(/\n{3,}/g, '\n\n').trim();

// Target customer phone number (filter out groups)
const from = $('Filter Mesej Pelanggan').first().json.body.from || $('Filter Mesej Pelanggan').first().json.body.payload?.from || '';
const customerChatId = from.includes('@g.us') || from.includes('@broadcast') ? '' : from;

if (!customerChatId) {
  return [{ json: { chatId: '', replyText: '', skipped: true, reason: 'group_or_broadcast' } }];
}

return [{
  json: {
    chatId: customerChatId,
    replyText: cleaned,
    processedAt: new Date().toISOString()
  }
}];
